import{_ as a,o as t,c as i,a3 as n}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"ATLAS Plugin Template","description":"Create an ATLAS plugin from the official GitHub template.","frontmatter":{"title":"ATLAS Plugin Template","description":"Create an ATLAS plugin from the official GitHub template."},"headers":[],"relativePath":"en/projects/atlas-plugins/plugin-template.md","filePath":"en/projects/atlas-plugins/plugin-template.md","lastUpdated":1792861636000}'),s={name:"en/projects/atlas-plugins/plugin-template.md"};function l(r,e,o,p,d,c){return t(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="atlas-plugin-template" tabindex="-1">ATLAS Plugin Template <a class="header-anchor" href="#atlas-plugin-template" aria-label="Permalink to &quot;ATLAS Plugin Template&quot;">​</a></h1><p>The <a href="https://github.com/rockbaer2007/atlas-plugin-template" target="_blank" rel="noreferrer">official ATLAS Plugin Template on GitHub</a> is a ready-to-use repository for a single ATLAS plugin. Use GitHub&#39;s <strong>Use this template</strong> action to create your own repository.</p><h2 id="plugin-generator-in-administration" tabindex="-1">Plugin generator in Administration <a class="header-anchor" href="#plugin-generator-in-administration" aria-label="Permalink to &quot;Plugin generator in Administration&quot;">​</a></h2><p>ATLAS Administration includes a plugin generator for ID, name, description, version, entry path and capabilities. Choose an MDI icon from the locally bundled catalog or a custom PNG up to 512 KiB; the package includes the graphic and required license notices. PNG colors and transparency survive. It generates an editable HTML/CSS/JavaScript starter, package, <code>repository.json</code> and localized <code>README.md</code>, also downloadable separately. Review contents and paths before publication. The generator creates no GitHub repository and publishes nothing automatically. Supported manually imported packages are installed on the App server after compatibility checks and served under <code>/plugin-assets/&lt;slug&gt;/</code>. Their UI runs when opened in the browser; Runtime hooks are not automatically registered. Keep <code>entry</code> and package paths consistent.</p><p>Plugins with their own language selector inherit the saved ATLAS language preference when launched. A <code>language</code> parameter in the plugin URL takes precedence. If a plugin does not support the selected language, it uses its configured fallback language.</p><h2 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h2><ol><li><p>Open the template repository and choose <strong>Use this template</strong> → <strong>Create a new repository</strong>.</p></li><li><p>Clone your new repository and edit <code>plugins/atlas-plugin/atlas-plugin.json</code>. Set a unique plugin ID, name, version, description and only the capabilities the plugin actually needs.</p></li><li><p>Replace the example app in <code>plugins/atlas-plugin/</code> and replace <code>icon.svg</code>, <code>logo.svg</code> and <code>preview.svg</code> with your plugin assets.</p></li><li><p>Build and validate the package locally:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div></li><li><p>Update <code>repository.json</code> and <code>install.html</code> for your repository. The package builder copies the ID, name, version, descriptions and asset paths from the manifest and keeps the catalog in sync.</p></li><li><p>After pushing, the catalog is available at <code>https://raw.githubusercontent.com/&lt;owner&gt;/&lt;repo&gt;/main/repository.json</code> without GitHub Pages. Enable GitHub Pages separately if you want to publish <code>install.html</code>.</p></li><li><p>Add the catalog URL in ATLAS Administration and install the plugin for testing.</p></li></ol><h2 id="included" tabindex="-1">Included <a class="header-anchor" href="#included" aria-label="Permalink to &quot;Included&quot;">​</a></h2><p>The template contains a small example plugin, manifest, repository catalog, installation page, package builder, validation and a GitHub Actions workflow. The workflow runs the build and checks on pushes and pull requests.</p><p>Bump the plugin version for every release and run <code>npm run build</code> afterwards. Keep the plugin ID stable after publication. Review permissions and declared capabilities before publishing.</p><h2 id="current-installation-scope" tabindex="-1">Current installation scope <a class="header-anchor" href="#current-installation-scope" aria-label="Permalink to &quot;Current installation scope&quot;">​</a></h2><p>The App server installs validated repository and imported packages in persistent plugin storage and serves static web files under <code>/plugin-assets/&lt;slug&gt;/</code>. Opening them runs their JavaScript in the browser; arbitrary Node modules or Runtime hooks are not automatically registered. Installation is not a sandbox: review package contents and browser code before opening. Package files contain text or explicitly marked Base64 assets; up to 300 files and 20 MB per package. Host larger binary assets separately.</p><p>See <a href="./repository-format">Repository Format</a> for catalog and package details. Template repository: <a href="https://github.com/rockbaer2007/atlas-plugin-template" target="_blank" rel="noreferrer">rockbaer2007/atlas-plugin-template</a>.</p>`,13)])])}const h=a(s,[["render",l]]);export{g as __pageData,h as default};
